package com.eventmgr.util;
import com.google.gson.*;import javax.servlet.*;import javax.servlet.http.*;import java.io.*;import java.util.*;
public abstract class ApiServlet extends HttpServlet {
 public static final Gson GSON=new Gson();public static void send(HttpServletResponse r,int s,Object b)throws IOException{r.setStatus(s);r.setContentType("application/json");r.setCharacterEncoding("UTF-8");r.getWriter().write(GSON.toJson(b));}public static void message(HttpServletResponse r,int s,String m)throws IOException{send(r,s,Map.of("message",m));}public static void error(HttpServletResponse r,int s,String m)throws IOException{send(r,s,Map.of("error",m));}
 @Override protected void service(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");try{super.service(q,r);}catch(ApiError e){error(r,e.status,e.getMessage());}catch(DbException e){if(e.sqlState!=null&&e.sqlState.startsWith("23"))error(r,409,"That record already exists or is in use.");else{log("Database error",e);error(r,500,"Database error. Check MySQL and db.properties.");}}catch(RuntimeException e){log("Unexpected error",e);error(r,500,"Something went wrong on the server.");}}
 protected User me(HttpServletRequest q){HttpSession s=q.getSession(false);User u=s==null?null:(User)s.getAttribute("user");if(u==null)throw new ApiError(401,"Please sign in");return u;}protected String[] segs(HttpServletRequest q){String p=q.getPathInfo();return p==null||p.equals("/")?new String[0]:p.substring(1).split("/");}
 protected long id(String x){try{return Long.parseLong(x);}catch(Exception e){throw new ApiError(400,"Invalid id");}}protected JsonObject body(HttpServletRequest q){try{JsonElement e=JsonParser.parseReader(q.getReader());return e!=null&&e.isJsonObject()?e.getAsJsonObject():new JsonObject();}catch(Exception e){throw new ApiError(400,"Invalid JSON body");}}
 protected String str(JsonObject b,String k,boolean req){JsonElement e=b.get(k);String v=e!=null&&!e.isJsonNull()?e.getAsString().trim():"";if(req&&v.isEmpty())throw new ApiError(400,"Missing required field: "+k);return v;}protected double num(JsonObject b,String k,double min,double max){try{double x=Double.parseDouble(str(b,k,true));if(x<min||x>max)throw new Exception();return x;}catch(Exception e){throw new ApiError(400,k+" is out of range");}}
}
